#!/usr/bin/env python3
"""Run the public RDF4J oracle on a fresh copy of a preserved crash image."""
# Some portions generated by Codex
from __future__ import annotations

import argparse
import json
from pathlib import Path
import signal
import sys
from typing import Any

from runner_common import (
    add_seed_iso_builder_argument,
    backend_control,
    build_artifact_manifest,
    copy_and_hash,
    copy_file_exclusive,
    create_fresh_directory,
    create_qcow_overlay,
    create_seed_iso,
    guest_classpath,
    guest_qemu_arguments,
    require_executable,
    require_free_tcp_ports,
    require_regular_file,
    resolve_seed_iso_builder,
    sha256_file,
    start_backend,
    start_logged_process,
    stop_process,
    wait_for_path,
    write_json_exclusive,
    write_text_exclusive,
)

SCRIPT_DIR = Path(__file__).resolve().parent
GUEST_DIR = SCRIPT_DIR / "guest"
DATA_BYTES = 128 * 1024 * 1024


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--scratch-root", required=True, type=Path,
                        help="new, non-existing directory for all copies and logs")
    parser.add_argument("--repo-root", required=True, type=Path)
    parser.add_argument("--host-classpath-file", required=True, type=Path)
    parser.add_argument("--source-image", required=True, type=Path,
                        help="preserved 128 MiB raw image; opened read-only and copied before recovery")
    parser.add_argument("--source-witness", required=True, type=Path)
    parser.add_argument("--source-namespace-witness", required=True, type=Path)
    parser.add_argument("--source-final-ack", required=True, type=Path)
    parser.add_argument("--os-base-image", required=True, type=Path)
    parser.add_argument("--firmware-code", required=True, type=Path)
    parser.add_argument("--firmware-vars-template", required=True, type=Path)
    parser.add_argument("--qemu", required=True, type=Path)
    parser.add_argument("--qemu-img", required=True, type=Path)
    add_seed_iso_builder_argument(parser)
    parser.add_argument("--port", required=True, type=int)
    parser.add_argument("--accel", default="hvf")
    parser.add_argument("--cpu", default="host")
    parser.add_argument("--smp", type=int, default=4)
    parser.add_argument("--memory-mib", type=int, default=4096)
    parser.add_argument("--timeout-seconds", type=int, default=300)
    return parser.parse_args()


def validate_inputs(args: argparse.Namespace) -> dict[str, Any]:
    repo = args.repo_root.expanduser().resolve(strict=True)
    if not repo.is_dir() or not (repo / ".m2_repo").is_dir():
        raise FileNotFoundError("repository and its .m2_repo must exist")
    source_image = require_regular_file(args.source_image, "preserved source image")
    if source_image.stat().st_size != DATA_BYTES:
        raise ValueError(f"source image must be exactly {DATA_BYTES} bytes: {source_image}")
    source_witness = require_regular_file(args.source_witness, "source witness")
    namespace_witness = require_regular_file(args.source_namespace_witness, "source namespace witness")
    final_ack = require_regular_file(args.source_final_ack, "source final acknowledgment")
    if not source_witness.read_text(encoding="utf-8").strip():
        raise ValueError("source witness is empty")
    if not namespace_witness.read_text(encoding="utf-8").strip():
        raise ValueError("source namespace witness is empty")
    seed_iso_tool, seed_iso_builder = resolve_seed_iso_builder(args)
    values = {
        "repo_root": repo,
        "source_image": source_image,
        "source_witness": source_witness,
        "namespace_witness": namespace_witness,
        "final_ack": final_ack,
        "os_image": require_regular_file(args.os_base_image, "OS base image"),
        "firmware_code": require_regular_file(args.firmware_code, "UEFI code image"),
        "firmware_vars": require_regular_file(args.firmware_vars_template, "UEFI vars template"),
        "qemu": require_executable(args.qemu, "QEMU"),
        "qemu_img": require_executable(args.qemu_img, "qemu-img"),
        "seed_iso_tool": require_executable(seed_iso_tool, seed_iso_builder),
        "seed_iso_builder": seed_iso_builder,
        "classpath_file": require_regular_file(args.host_classpath_file, "host classpath file"),
        "backend": require_regular_file(repo / "scripts/lmdb-crashlab/volatile_nbd.py", "checked-in NBD backend"),
    }
    values["artifact_manifest"] = build_artifact_manifest(repo)
    values["classpath_value"], values["classpath_manifest"] = guest_classpath(values["classpath_file"], repo)
    if not 1 <= args.port <= 65535 or args.timeout_seconds < 1:
        raise ValueError("port and timeout must be in range")
    require_free_tcp_ports("127.0.0.1", (args.port,))
    if args.smp < 1 or args.memory_mib < 1024:
        raise ValueError("guest must have at least one CPU and 1024 MiB RAM")
    return values


def main() -> int:
    args = parse_args()
    inputs = validate_inputs(args)
    root = create_fresh_directory(args.scratch_root)
    results, qemu_root, nbd_root = root / "results", root / "qemu", root / "nbd"
    results.mkdir()
    qemu_root.mkdir()
    nbd_root.mkdir()
    preserved_dir = results / "pre-recovery-image"
    working_dir = root / "working-image"
    preserved_dir.mkdir()
    working_dir.mkdir()
    source_hash_before = sha256_file(inputs["source_image"])
    preserved = copy_and_hash(inputs["source_image"], preserved_dir / "data.raw")
    working = copy_and_hash(inputs["source_image"], working_dir / "data.raw")
    copy_file_exclusive(inputs["source_witness"], results / "actual-ack-witness.tsv")
    copy_file_exclusive(inputs["namespace_witness"], results / "actual-namespace-witness.tsv")
    copy_file_exclusive(inputs["final_ack"], results / "actual-lmdb-final-ack")
    copy_file_exclusive(inputs["classpath_file"], results / "actual-build-classpath-host.txt")
    write_text_exclusive(results / "actual-build-classpath-guest.txt", inputs["classpath_value"] + "\n")
    write_json_exclusive(results / "actual-current-build-manifest.json", inputs["artifact_manifest"])
    write_json_exclusive(results / "actual-classpath-manifest.json", inputs["classpath_manifest"])
    recovery_os = qemu_root / "recovery-os.qcow2"
    create_qcow_overlay(inputs["qemu_img"], inputs["os_image"], recovery_os,
                        qemu_root / "recovery-os-overlay.log")
    recovery_vars = qemu_root / "recovery-vars.fd"
    copy_file_exclusive(inputs["firmware_vars"], recovery_vars)
    recovery_seed = create_seed_iso(inputs["seed_iso_tool"], qemu_root, "recovery", "boot-recovery.sh",
                                    builder=inputs["seed_iso_builder"])
    source_hashes = {
        "source_image": source_hash_before,
        "source_witness": sha256_file(inputs["source_witness"]),
        "source_namespace_witness": sha256_file(inputs["namespace_witness"]),
        "source_final_ack": sha256_file(inputs["final_ack"]),
        "backend": sha256_file(inputs["backend"]),
        "os_base": sha256_file(inputs["os_image"]),
        "oracle_source": sha256_file(GUEST_DIR / "Rdf4jCrashlabOracle.java"),
        "boot_script": sha256_file(GUEST_DIR / "boot-recovery.sh"),
        "runner_source": sha256_file(SCRIPT_DIR / "run_recovery_only.py"),
        "shared_runner_source": sha256_file(SCRIPT_DIR / "runner_common.py"),
    }
    write_json_exclusive(results / "actual-recovery-input-manifest.json", {
        "source_preserved_image": str(inputs["source_image"]),
        "source_preserved_image_sha256": source_hash_before,
        "preserved_copy": preserved,
        "working_copy": working,
        "source_hashes": source_hashes,
        "checked_in_backend_sha256": source_hashes["backend"],
        "qemu_data_cache": "cache=writeback; virtio write-cache=on; FLUSH/FUA enabled; no -snapshot or unsafe cache flags",
        "repository_and_m2_shares": "9p read-only",
        "results_share": "9p read-write, unique fresh root",
        "current_build_manifest": str(results / "actual-current-build-manifest.json"),
        "java_helper": "Rdf4jCrashlabOracle; public RDF4J APIs only; no reflection",
        "claim_boundary": "QEMU Linux guest and volatile NBD device-loss simulation only; no physical host power-loss claim.",
    })

    backend_process = qemu_process = None
    control = nbd_root / "recovery-control.sock"
    events = results / "actual-recovery-nbd-events.jsonl"
    error: BaseException | None = None
    try:
        backend_process = start_backend(python=Path(sys.executable), backend=inputs["backend"],
                                        image=working_dir / "data.raw", control=control,
                                        port=args.port, events=events,
                                        log=results / "actual-recovery-backend.log",
                                        command_record=results / "actual-recovery-backend-command.json")
        initial_status = backend_control(Path(sys.executable), inputs["backend"], control, "status")
        write_json_exclusive(results / "actual-recovery-backend-initial-status.json", initial_status)
        command = guest_qemu_arguments(
            qemu=inputs["qemu"], name="rdf4j-crashlab-recovery-only", accel=args.accel, cpu=args.cpu,
            smp=args.smp, memory_mib=args.memory_mib, firmware_code=inputs["firmware_code"],
            firmware_vars=recovery_vars, os_disk=recovery_os, data_port=args.port,
            seed_iso=recovery_seed, serial_log=results / "actual-recovery-serial.log",
            repo_root=inputs["repo_root"], results=results)
        write_json_exclusive(results / "actual-recovery-qemu-command.json", command)
        qemu_process = start_logged_process(command, results / "actual-recovery-qemu.log")
        marker = wait_for_path(qemu_process,
                               [results / "actual-lmdb-recovery-done", results / "actual-recovery-failed"],
                               args.timeout_seconds)
        stop_process(qemu_process, signal.SIGKILL)
        qemu_process = None
        final_status = backend_control(Path(sys.executable), inputs["backend"], control, "status")
        write_json_exclusive(results / "actual-recovery-backend-status-after-oracle.json", final_status)
    except BaseException as exc:
        error = exc
        marker = None
    finally:
        stop_process(qemu_process, signal.SIGKILL)
        stop_process(backend_process, signal.SIGINT)

    oracle_log = results / "actual-recovery-oracle.log"
    oracle_text = oracle_log.read_text(encoding="utf-8", errors="replace") if oracle_log.exists() else ""
    public_checks_completed = "PUBLIC_INDEX_CONTEXT_SPARQL_CHECKS=COMPLETED" in oracle_text
    findings = [line.removeprefix("FINDING=") for line in oracle_text.splitlines()
                if line.startswith("FINDING=")]
    if error is not None:
        result = "RECOVERY_RUNNER_ERROR"
    elif marker is not None and marker.name == "actual-lmdb-recovery-done" and not findings:
        result = "PUBLIC_ORACLE_PASS"
    elif marker is not None and marker.name == "actual-recovery-failed" and public_checks_completed:
        result = "PUBLIC_ORACLE_COMPLETED_WITH_FINDINGS"
    else:
        result = "PUBLIC_ORACLE_INCOMPLETE"
    source_hash_after = sha256_file(inputs["source_image"])
    source_paths = {
        "source_image": inputs["source_image"],
        "source_witness": inputs["source_witness"],
        "source_namespace_witness": inputs["namespace_witness"],
        "source_final_ack": inputs["final_ack"],
        "backend": inputs["backend"],
        "os_base": inputs["os_image"],
        "oracle_source": GUEST_DIR / "Rdf4jCrashlabOracle.java",
        "boot_script": GUEST_DIR / "boot-recovery.sh",
        "runner_source": SCRIPT_DIR / "run_recovery_only.py",
        "shared_runner_source": SCRIPT_DIR / "runner_common.py",
    }
    source_unchanged = all(sha256_file(path) == source_hashes[name]
                           for name, path in source_paths.items())
    try:
        build_unchanged = build_artifact_manifest(inputs["repo_root"]) == inputs["artifact_manifest"]
        _, classpath_after = guest_classpath(inputs["classpath_file"], inputs["repo_root"])
        classpath_unchanged = classpath_after == inputs["classpath_manifest"]
    except (FileNotFoundError, ValueError):
        build_unchanged = classpath_unchanged = False
    if not source_unchanged or not build_unchanged or not classpath_unchanged:
        result = "READ_ONLY_INPUT_CHANGED"
    if source_hash_after != source_hash_before:
        result = "SOURCE_IMAGE_CHANGED"
    report = {
        "result": result,
        "fault_scope": "recovery-only public API boot from a copied preserved raw image; simulated QEMU guest and virtual device behavior, not physical host power loss",
        "source_pre_recovery_sha256": source_hash_before,
        "source_pre_recovery_sha256_after_run": source_hash_after,
        "source_image_unchanged": source_hash_after == source_hash_before,
        "read_only_sources_unchanged": source_unchanged,
        "compiled_classes_unchanged": build_unchanged,
        "classpath_artifacts_unchanged": classpath_unchanged,
        "pre_recovery_copy": preserved,
        "working_image": str(working_dir / "data.raw"),
        "working_image_sha256_after_recovery": sha256_file(working_dir / "data.raw"),
        "checked_in_backend_sha256": source_hashes["backend"],
        "recovery_backend_status": (results / "actual-recovery-backend-status-after-oracle.json").read_text()
            if (results / "actual-recovery-backend-status-after-oracle.json").exists() else None,
        "oracle_log": str(oracle_log),
        "oracle_completed_public_checks": public_checks_completed,
        "findings": findings,
        "guest_jdk": (results / "actual-recovery-java-version.txt").read_text(errors="replace")
            if (results / "actual-recovery-java-version.txt").exists() else None,
        "current_build_manifest": str(results / "actual-current-build-manifest.json"),
        "boundary": "QEMU Linux guest and checked-in volatile NBD device-loss simulation only; no physical host/APFS/SSD power-loss claim.",
    }
    write_json_exclusive(results / "actual-recovery-only-report.json", report)
    if error is not None:
        write_text_exclusive(results / "actual-recovery-runner-failure.txt",
                             type(error).__name__ + ": " + str(error) + "\n")
        raise error
    print(json.dumps(report, indent=2, sort_keys=True))
    if result == "PUBLIC_ORACLE_PASS":
        return 0
    return 2 if result == "PUBLIC_ORACLE_COMPLETED_WITH_FINDINGS" else 3


if __name__ == "__main__":
    raise SystemExit(main())
